const rawSiteId = String($json.site_id || '').trim().toUpperCase();
const chatId = String($json.chat_id || '').trim();
if (!/^[A-Z0-9][A-Z0-9_-]{1,31}$/.test(rawSiteId) || !chatId) {
  throw new Error('INVALID_CAPTURE_INPUT');
}
return [{ json: { site_id: rawSiteId, chat_id: chatId, started_at_ms: Date.now() } }];

const input = $('Validate Site ID').first().json;
const minted = $json;
if (typeof minted.capture_url !== 'string' || !minted.capture_url.startsWith('https://')) {
  throw new Error('CAPTURE_TOKEN_MINT_FAILED');
}
const ready = '[data-capture-state="ready"][data-capture-site-id="' + input.site_id + '"]';
const query = `mutation CaptureSiteDetail($url: String!, $ready: String!) {
  viewport(width: 1200, height: 1000, deviceScaleFactor: 1.5) { width height deviceScaleFactor }
  goto(url: $url, waitUntil: domContentLoaded) { status time }
  ready: waitForSelector(selector: $ready, visible: true, timeout: 12000) { selector time }
  modal: waitForSelector(selector: ".site-detail-modal", visible: true, timeout: 1000) { width height }
  capture: screenshot(selector: ".site-detail-modal", type: png, captureBeyondViewport: true, optimizeForSpeed: true, waitForImages: true, timeout: 12000) { base64 format time }
}`;
return [{ json: { ...input, token_issue_ms: Date.now() - input.started_at_ms, query, variables: { url: minted.capture_url, ready } } }];

const encoded = $json.data?.capture?.base64;
if (typeof encoded !== 'string' || !encoded.length) throw new Error('CAPTURE_PNG_MISSING');
const bytes = Buffer.from(encoded, 'base64');
if (bytes.subarray(0, 8).toString('hex') !== '89504e470d0a1a0a') throw new Error('CAPTURE_PNG_INVALID');
if (bytes.length === 0 || bytes.length > 50 * 1024 * 1024) throw new Error('CAPTURE_PNG_SIZE_INVALID');
const width = bytes.readUInt32BE(16);
const height = bytes.readUInt32BE(20);
const modal = $json.data?.modal;
if (!modal || width + 2 < Math.floor(modal.width * 1.5) || height + 2 < Math.floor(modal.height * 1.5)) throw new Error('CAPTURE_PNG_CROPPED');
const input = $('Validate Site ID').first().json;
return [{ json: { site_id: input.site_id, chat_id: input.chat_id, started_at_ms: input.started_at_ms, token_issue_ms: $('Prepare Browserless').first().json.token_issue_ms, capture_ready_ms: $json.data.ready.time, screenshot_ms: $json.data.capture.time, png_width: width, png_height: height }, binary: { data: { data: encoded, mimeType: 'image/png', fileName: 'site-detail-' + input.site_id + '.png' } } }];

const upload = $('Prepare Telegram Upload').first().json;
const totalMs = Date.now() - upload.started_at_ms;
console.log(JSON.stringify({ event: 'site_detail_capture', request_id: $execution.id, site_id: upload.site_id, token_issue_ms: upload.token_issue_ms, capture_ready_ms: upload.capture_ready_ms, screenshot_ms: upload.screenshot_ms, telegram_upload_ms: Date.now() - upload.telegram_started_at_ms, total_ms: totalMs, result: 'sent' }));
return [{ json: { sent: true, site_id: upload.site_id, telegram_message_id: $json.result?.message_id ?? $json.message_id, elapsed_ms: totalMs } }];
